export default async function next(
  { values, runId, documentId, relayUrl, indexHost, acknowledge, resolution },
  ctx,
) {
  if (
    !runId ||
    !documentId ||
    !/^https:\/\//.test(relayUrl) ||
    !/^https:\/\//.test(indexHost) ||
    relayUrl.includes("YOUR_") ||
    indexHost.includes("YOUR_")
  )
    throw Error("Configure run, document and endpoints");
  const head = values?.[0] || [],
    u = head.indexOf("File URL"),
    n = head.indexOf("10Q");
  if (u < 0 || n < 0) throw Error("Sheet needs File URL and 10Q headers");
  const files = values
    .slice(1)
    .filter((r) => r[u])
    .map((r) => {
      const url = String(r[u]),
        m = url.match(/\/d\/([\w-]+)/) || url.match(/[?&]id=([\w-]+)/);
      if (!m || !r[n]) throw Error("Expected Drive file URL and 10Q name");
      return { id: m[1], name: String(r[n]) };
    });
  if (files.length < 3 || new Set(files.map((f) => f.id)).size !== files.length)
    throw Error("Expected at least three distinct earnings PDFs");
  const key = "earnings:" + runId;
  let s = await ctx.state.get(key);
  if (!s) {
    s = { files, documentId, index: 0, offset: 0, phase: "index", contexts: [], pending: null };
    await ctx.state.set(key, s);
  }
  if (s.documentId !== documentId || JSON.stringify(s.files) !== JSON.stringify(files))
    throw Error("Run ID reused for different inputs");
  if (s.pending) {
    if (acknowledge !== s.pending || !["confirmed", "absent"].includes(resolution))
      throw Error("Inspect pending " + s.pending);
    if (resolution === "confirmed") {
      if (s.phase === "index") {
        s.offset = s.pendingNextOffset;
        s.phase = s.pendingMore ? "index" : "search";
      } else s.phase = "done";
    }
    s.pending = null;
    await ctx.state.set(key, s);
  }
  if (s.index >= s.files.length && s.phase === "index") {
    s.phase = "report";
    await ctx.state.set(key, s);
  }
  const file = s.files[s.index] || { id: "", name: "" };
  return {
    key,
    action: s.phase,
    index: s.index,
    offset: s.offset,
    fileId: file.id,
    name: file.name,
    relayUrl,
    namespace: runId,
    context: s.contexts.map((c) => `File ${c.name} (${c.id}):\n${c.text}`).join("\n\n"),
    documentId,
    request: { fileId: file.id, name: file.name },
  };
}

