export default function chunks({ body, fileId, name, offset }) {
  if (
    body?.fileId !== fileId ||
    body?.name !== name ||
    typeof body?.text !== "string" ||
    !body.text.trim()
  )
    throw Error("Invalid PDF extraction receipt");
  const chunks = [];
  for (let i = offset; i < body.text.length && chunks.length < 4; i += 880) {
    chunks.push(body.text.slice(i, i + 1000));
    if (i + 1000 >= body.text.length) break;
  }
  if (!chunks.length) throw Error("Invalid PDF chunk offset");
  const nextOffset = offset + chunks.length * 880,
    more = offset + (chunks.length - 1) * 880 + 1000 < body.text.length,
    model = "models/gemini-embedding-001";
  return {
    chunks,
    more,
    nextOffset,
    request: {
      requests: chunks.map((text) => ({
        model,
        content: { parts: [{ text }] },
        outputDimensionality: 3072,
      })),
    },
  };
}

