export default async function reserve(
  { key, index, offset, nextOffset, more, fileId, name, namespace, chunks, response },
  ctx,
) {
  const s = await ctx.state.get(key);
  if (
    !s ||
    s.phase !== "index" ||
    s.index !== index ||
    s.files[index].id !== fileId ||
    s.offset !== offset ||
    s.pending
  )
    throw Error("Invalid file state");
  if (!Array.isArray(response?.embeddings) || response.embeddings.length !== chunks.length)
    throw Error("Invalid embeddings");
  const vectors = chunks.map((text, i) => {
    const values = response.embeddings[i]?.values;
    if (!Array.isArray(values) || values.length !== 3072) throw Error("Invalid vector");
    return { id: fileId + ":" + (offset + i * 880), values, metadata: { fileId, name, text } };
  });
  s.pending = key + ":index:" + index + ":" + offset;
  s.pendingMore = more;
  s.pendingNextOffset = nextOffset;
  await ctx.state.set(key, s);
  return { vectors, count: vectors.length };
}

