export default async function confirm({ key, index, offset, count, upsertedCount }, ctx) {
  const s = await ctx.state.get(key);
  if (upsertedCount !== count || s?.pending !== key + ":index:" + index + ":" + offset)
    throw Error("Unknown Pinecone upsert");
  s.pending = null;
  s.offset = s.pendingNextOffset;
  s.phase = s.pendingMore ? "index" : "search";
  await ctx.state.set(key, s);
  return { ok: true };
}

