export default async function save({ key, index, fileId, name, matches }, ctx) {
  const s = await ctx.state.get(key);
  if (
    !s ||
    s.phase !== "search" ||
    s.index !== index ||
    s.files[index].id !== fileId ||
    !Array.isArray(matches)
  )
    throw Error("Invalid Pinecone query result");
  const text = matches
    .map((m) => m.metadata?.text)
    .filter((x) => typeof x === "string" && x.trim())
    .join("\n\n");
  if (!text) throw Error("No passages for " + name);
  s.contexts.push({ id: fileId, name, text });
  s.index++;
  s.offset = 0;
  s.phase = "index";
  await ctx.state.set(key, s);
  return { ok: true };
}

