export default async function reserve({ key, report }, ctx) {
  const s = await ctx.state.get(key);
  if (!s || s.phase !== "report" || s.pending || !report?.trim())
    throw Error("Invalid report state");
  s.pending = key + ":report";
  await ctx.state.set(key, s);
  return { requests: [{ insertText: { endOfSegmentLocation: {}, text: report + "\n" } }] };
}

