export default async function confirm({ key, documentId, actualDocumentId }, ctx) {
  const s = await ctx.state.get(key);
  if (!s || s.pending !== key + ":report" || documentId !== actualDocumentId)
    throw Error("Unknown document update");
  s.pending = null;
  s.phase = "done";
  await ctx.state.set(key, s);
  return { ok: true };
}
